CREATE TABLE admins (
  id TINYINT UNSIGNED NOT NULL PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  email VARCHAR(190) NOT NULL UNIQUE,
  password_hash VARCHAR(255) NOT NULL,
  active TINYINT(1) NOT NULL DEFAULT 1,
  mfa_enabled TINYINT(1) NOT NULL DEFAULT 0,
  mfa_secret TEXT NULL,
  mfa_pending_secret TEXT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT one_admin CHECK (id = 1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE admin_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_id TINYINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,type ENUM('access','mfa') NOT NULL,ip VARCHAR(45) NOT NULL,user_agent VARCHAR(255) NOT NULL,expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(expires_at),FOREIGN KEY(admin_id) REFERENCES admins(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE mfa_recovery_codes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_id TINYINT UNSIGNED NOT NULL,code_hash CHAR(64) NOT NULL,used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(admin_id) REFERENCES admins(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ip VARCHAR(45) NOT NULL,successful TINYINT(1) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(ip,created_at)) ENGINE=InnoDB;
CREATE TABLE applications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,public_id CHAR(32) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,url VARCHAR(500) NOT NULL,environment ENUM('Production','Staging','Development') NOT NULL DEFAULT 'Production',status ENUM('healthy','degraded','maintenance') NOT NULL DEFAULT 'healthy',ingestion_key_hash CHAR(64) NOT NULL,accent CHAR(7) NOT NULL DEFAULT '#3979ff',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE visitors (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,application_id BIGINT UNSIGNED NOT NULL,visitor_id VARCHAR(190) NOT NULL,user_id VARCHAR(190) NULL,first_seen_at DATETIME NOT NULL,last_seen_at DATETIME NOT NULL,ip_hash CHAR(64) NULL,country CHAR(2) NULL,device VARCHAR(50) NULL,browser VARCHAR(50) NULL,UNIQUE(application_id,visitor_id),INDEX(application_id,last_seen_at),FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,application_id BIGINT UNSIGNED NOT NULL,visitor_id VARCHAR(190) NOT NULL,session_id VARCHAR(190) NULL,user_id VARCHAR(190) NULL,event_name VARCHAR(100) NOT NULL,page_url VARCHAR(1000) NULL,referrer VARCHAR(1000) NULL,properties JSON NULL,occurred_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(application_id,occurred_at),INDEX(application_id,event_name,occurred_at),FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE payment_connections (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,application_id BIGINT UNSIGNED NOT NULL,provider ENUM('stripe','paystack','flutterwave') NOT NULL,display_name VARCHAR(100) NOT NULL,credentials_encrypted MEDIUMTEXT NOT NULL,webhook_secret_encrypted TEXT NOT NULL,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(application_id,provider),FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,application_id BIGINT UNSIGNED NOT NULL,provider VARCHAR(30) NOT NULL,provider_reference VARCHAR(190) NOT NULL,customer_name VARCHAR(190) NULL,customer_email VARCHAR(190) NULL,plan_name VARCHAR(120) NULL,amount_minor BIGINT NOT NULL DEFAULT 0,currency CHAR(3) NOT NULL DEFAULT 'USD',status ENUM('paid','failed','refunded','pending') NOT NULL,paid_at DATETIME NULL,raw_payload JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(provider,provider_reference),INDEX(application_id,created_at),FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE alerts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,application_id BIGINT UNSIGNED NULL,severity ENUM('info','warning','critical') NOT NULL,title VARCHAR(190) NOT NULL,message TEXT NOT NULL,resolved_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(resolved_at,created_at),FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_id TINYINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,entity_type VARCHAR(50) NULL,entity_id VARCHAR(100) NULL,metadata JSON NULL,ip VARCHAR(45) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(created_at)) ENGINE=InnoDB;

